package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Copula control functions for one PLS/GSCA score equation, with both stages refitted. */
public final class ComponentCopula {
    private ComponentCopula(){}
    public record Specification(int target,int[] endogenous,CopulaRegression.Method method,CopulaRegression.PlottingPosition plottingPosition){public Specification{endogenous=endogenous.clone();Objects.requireNonNull(method);Objects.requireNonNull(plottingPosition);if(target<0||endogenous.length==0||Arrays.stream(endogenous).anyMatch(i->i<0||i==target)||Arrays.stream(endogenous).distinct().count()!=endogenous.length)throw new IllegalArgumentException("Select a target and distinct potentially endogenous parent constructs.");}@Override public int[] endogenous(){return endogenous.clone();}}
    public record Fit(ComponentScores.Fit firstStage,Specification specification,List<Integer> parents,CopulaRegression.Fit correction,List<String> warnings){public Fit{parents=List.copyOf(parents);warnings=List.copyOf(warnings);}}
    public record Resampled(Fit point,Bootstrap.Result inference){}
    public static Fit fit(double[][] data,ComponentScores.Model model,Specification specification){var first=ComponentScores.fit(data,model);return describe(first,specification,first.scores());}
    private static Fit describe(ComponentScores.Fit first,Specification specification,double[][] scores){var model=first.model();List<String> names=model.names();if(specification.target()>=names.size())throw new IllegalArgumentException("Copula target is outside the component model.");List<Integer> parents=model.paths().stream().filter(path->path.target()==specification.target()).map(PlsSem.Edge::source).distinct().sorted().toList();if(parents.isEmpty())throw new IllegalArgumentException("Choose a target with structural parents.");int[] local=new int[specification.endogenous().length];for(int i=0;i<local.length;i++){local[i]=parents.indexOf(specification.endogenous()[i]);if(local[i]<0)throw new IllegalArgumentException("Every potentially endogenous construct must be a direct parent of the chosen target.");}double[][] x=new double[scores.length][parents.size()];double[] y=new double[scores.length];for(int row=0;row<scores.length;row++){y[row]=scores[row][specification.target()];for(int col=0;col<parents.size();col++)x[row][col]=scores[row][parents.get(col)];}var correction=CopulaRegression.fit(x,y,new CopulaRegression.Model(parents.stream().map(names::get).toList(),local,specification.method(),specification.plottingPosition()));List<String>warnings=new ArrayList<>(first.warnings());warnings.addAll(correction.warnings());warnings.add("This correction applies to one selected component-score equation. Other structural equations and their total/indirect effects are not silently replaced. Identification, valid exogeneity and distributional assumptions remain substantive; generated proxies do not guarantee causal identification.");warnings.add("Corrected coefficients are in centered unit-variance component-score units. Augmented R-squared includes generated controls and is separate from the original first-stage structural R-squared. Original-unit intercept inference is not supplied for centered/generated-control score equations.");return new Fit(first,specification,parents,correction,warnings);}
    public static Resampled bootstrap(double[][] data,ComponentScores.Model model,Specification specification,Bootstrap.Options options,IntConsumer progress){Fit point=fit(data,model,specification);double[][] original=point.firstStage().scores();List<Bootstrap.Parameter> parameters=parameters(point);double[] values=values(point);var result=Resampling.run(data,parameters,values,options,(sample,rows)->{var first=ComponentScores.fit(sample,model);var aligned=ComponentScores.align(first.scores(),original,rows);return values(describe(first,specification,aligned));},progress,"Full-pipeline "+model.estimator()+" component-score copula correction","Every case/jackknife draw refits the component estimator; component signs align to original scores at sampled row indices before midranks, normal scores, 2sCOPE residuals and augmented regression are recomputed. No fixed original scores or generated controls are reused.");List<String>warnings=new ArrayList<>(result.warnings());warnings.addAll(point.warnings());result=new Bootstrap.Result(result.options(),result.method(),result.randomGenerator(),result.signHandling(),result.successful(),result.failed(),result.failures(),result.estimates(),warnings,result.estimator());return new Resampled(point,result);}
    private static List<Bootstrap.Parameter> parameters(Fit point){List<Bootstrap.Parameter> result=new ArrayList<>();int parents=point.parents().size();for(int j=1;j<point.correction().coefficients().size();j++){var coefficient=point.correction().coefficients().get(j);int source=j<=parents?point.parents().get(j-1):point.specification().endogenous()[j-parents-1];result.add(new Bootstrap.Parameter(j<=parents?"Corrected structural":"Generated copula control",source,point.specification().target(),source,coefficient.name()));}for(int j=1;j<=parents;j++){int source=point.parents().get(j-1);String name=point.correction().coefficients().get(j).name();result.add(new Bootstrap.Parameter("Uncorrected structural",source,point.specification().target(),source,name));result.add(new Bootstrap.Parameter("Structural correction difference",source,point.specification().target(),source,name));}return List.copyOf(result);}
    private static double[] values(Fit point){int parents=point.parents().size(),count=point.correction().coefficients().size()-1;double[] values=new double[count+2*parents];for(int j=1;j<=count;j++)values[j-1]=point.correction().coefficients().get(j).value();int index=count;for(int j=1;j<=parents;j++){var coefficient=point.correction().coefficients().get(j);values[index++]=coefficient.uncorrected();values[index++]=coefficient.difference();}return values;}
}
